   14	// Version is the current file schema version.
   15	const Version = 1
   16	
   17	// ErrNotFound is returned for unknown task IDs.
   18	var ErrNotFound = errors.New("task not found")
   19	
   20	type fileFormat struct {
   21		Version int          `json:"version"`
   22		NextID  int          `json:"next_id"`
   23		Tasks   []model.Task `json:"tasks"`
   24	}
   25	
   26	// Store is an in-memory view of the task file.
   27	type Store struct {
   28		path   string
   29		nextID int
   30		tasks  map[int]*model.Task
   31	}
   32	
   33	// Open loads the file at path. A missing file yields an empty store.
   34	func Open(path string) (*Store, error) {
   35		s := &Store{path: path, nextID: 1, tasks: map[int]*model.Task{}}
   36		data, err := os.ReadFile(path)
   37		if errors.Is(err, os.ErrNotExist) {
   38			return s, nil
   39		}
   40		if err != nil {
   41			return nil, err
   42		}
   43		var f fileFormat
   44		if err := json.Unmarshal(data, &f); err != nil {
   45			return nil, fmt.Errorf("store: parse %s: %w", path, err)
   46		}
   47		if f.Version > Version {
   48			return nil, fmt.Errorf("store: file version %d is newer than supported %d", f.Version, Version)
   49		}
   50		for i := range f.Tasks {
   51			t := f.Tasks[i]
   52			s.tasks[t.ID] = &t
   53			if t.ID >= s.nextID {
   54				s.nextID = t.ID + 1
   55			}
   56		}
   57		if f.NextID > s.nextID {
   58			s.nextID = f.NextID
   59		}
   60		return s, nil
   61	}
   62	
   63	// Save writes the store atomically.
   64	func (s *Store) Save() error {
   65		f := fileFormat{Version: Version, NextID: s.nextID, Tasks: s.All()}
   66		data, err := json.MarshalIndent(f, "", "  ")
   67		if err != nil {
   68			return err
   69		}
   70		tmp := s.path + ".tmp"
   71		if err := os.WriteFile(tmp, data, 0o644); err != nil {
   72			return err
   73		}
   74		return os.Rename(tmp, s.path)
   75	}
   76	
   77	// Add validates and inserts a task, assigning its ID.
   78	func (s *Store) Add(t model.Task) (model.Task, error) {
   79		if err := t.Validate(); err != nil {
   80			return model.Task{}, err
   81		}
   82		t.ID = s.nextID
   83		s.nextID++
   84		s.tasks[t.ID] = &t
   85		return t, nil
   86	}
   87	
   88	// Get returns a copy of a task.
   89	func (s *Store) Get(id int) (model.Task, error) {
   90		t, ok := s.tasks[id]
   91		if !ok {
   92			return model.Task{}, ErrNotFound
   93		}
   94		return *t, nil
   95	}
   96	
   97	// Update replaces a task after validation.
   98	func (s *Store) Update(t model.Task) error {
   99		if _, ok := s.tasks[t.ID]; !ok {
  100			return ErrNotFound
  101		}
  102		if err := t.Validate(); err != nil {
  103			return err
  104		}
  105		s.tasks[t.ID] = &t
  106		return nil
  107	}
  108	
  109	// Delete removes a task.
  110	func (s *Store) Delete(id int) error {
  111		if _, ok := s.tasks[id]; !ok {
  112			return ErrNotFound
  113		}
  114		delete(s.tasks, id)
  115		return nil
  116	}
  117	
  118	// All returns copies of all tasks ordered by ID.
  119	func (s *Store) All() []model.Task {
  120		out := make([]model.Task, 0, len(s.tasks))
  121		for _, t := range s.tasks {
  122			out = append(out, *t)
  123		}
  124		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
  125		return out
  126	}

