func Apply(tasks []model.Task, o Options) ([]model.Task, error) {
	var out []model.Task
	today := time.Date(o.Now.UTC().Year(), o.Now.UTC().Month(), o.Now.UTC().Day(), 0, 0, 0, 0, time.UTC)
