// Task is one tracked item.
type Task struct {
	ID       int        `json:"id"`
	Title    string     `json:"title"`
	Priority int        `json:"priority"`
	Done     bool       `json:"done"`
	Created  time.Time  `json:"created"`
	Tags     []string   `json:"tags,omitempty"`
	Due      *time.Time `json:"due,omitempty"`
}

// Validation errors.
var (
	ErrEmptyTitle  = errors.New("title must not be empty")
	ErrBadPriority = errors.New("priority must be between 1 and 5")
	ErrBadTag      = errors.New("invalid tag")
)

// DefaultPriority is used when none is given.
const DefaultPriority = 3

// tagRe matches a normalised tag.
var tagRe = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*$`)

// NormalizeTags trims and lower-cases each tag, de-duplicates and sorts
// them. It returns ErrBadTag if any tag does not match
// ^[a-z0-9][a-z0-9-]*$ after normalisation.
func NormalizeTags(tags []string) ([]string, error) {
	seen := make(map[string]bool)
	var out []string
	for _, tag := range tags {
		tag = strings.ToLower(strings.TrimSpace(tag))
		if !tagRe.MatchString(tag) {
			return nil, ErrBadTag
		}
		if !seen[tag] {
			seen[tag] = true
			out = append(out, tag)
		}
	}
	sort.Strings(out)
	return out, nil
}

// Validate checks the task fields.
func (t *Task) Validate() error {
	t.Title = strings.TrimSpace(t.Title)
	if t.Title == "" {
		return ErrEmptyTitle
	}
	if t.Priority < 1 || t.Priority > 5 {
		return ErrBadPriority
	}
	var err error
	if t.Tags, err = NormalizeTags(t.Tags); err != nil {
		return err
	}
	return nil
}
