package query

import (
	"fmt"
	"sort"
	"time"

	"example.com/tasker/internal/model"
)

// Options selects and orders tasks.
type Options struct {
	IncludeDone bool
	SortBy      string // "id" (default), "priority" or "due"
	Tags        []string
	Overdue     bool
	Now         time.Time // clock, used for Overdue
}

// Apply returns the matching tasks in order.
func Apply(tasks []model.Task, o Options) ([]model.Task, error) {
	nc := o.Now.UTC()
	today := time.Date(nc.Year(), nc.Month(), nc.Day(), 0, 0, 0, 0, time.UTC)
	var out []model.Task
	for _, t := range tasks {
		if t.Done && !o.IncludeDone {
			continue
		}
		if o.Overdue && (t.Done || t.Due == nil || !t.Due.Before(today)) {
			continue
		}
		if len(o.Tags) > 0 && !hasAllTags(t, o.Tags) {
			continue
		}
		out = append(out, t)
	}
	switch o.SortBy {
	case "", "id":
		sort.SliceStable(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	case "priority":
		sort.SliceStable(out, func(i, j int) bool {
			if out[i].Priority != out[j].Priority {
				return out[i].Priority < out[j].Priority
			}
			return out[i].ID < out[j].ID
		})
	case "due":
		sort.SliceStable(out, func(i, j int) bool {
			di, dj := out[i].Due, out[j].Due
			switch {
			case di == nil && dj == nil:
				return out[i].ID < out[j].ID
			case di == nil:
				return false // no due date sorts last
			case dj == nil:
				return true
			}
			if !di.Equal(*dj) {
				return di.Before(*dj)
			}
			return out[i].ID < out[j].ID
		})
	default:
		return nil, fmt.Errorf("unknown sort key %q", o.SortBy)
	}
	return out, nil
}

func hasAllTags(t model.Task, want []string) bool {
	have := make(map[string]bool, len(t.Tags))
	for _, tag := range t.Tags {
		have[tag] = true
	}
	for _, tag := range want {
		if !have[tag] {
			return false
		}
	}
	return true
}
