{"content":"package cli

import (
	"fmt"
	"strings"

	"example.com/tasker/internal/model"
)

// FormatTask renders one list line:
// "#<id> [x| ] P<priority> <title> (due YYYY-MM-DD) [tag1,tag2]",
// omitting the due and tag parts when empty.
func FormatTask(t model.Task) string {
	mark := " "
	if t.Done {
		mark = "x"
	}
	line := fmt.Sprintf("#%d [%s] P%d %s", t.ID, mark, t.Priority, t.Title)
	if t.Due != nil {
		line += " (due " + t.Due.UTC().Format("2006-01-02") + ")"
	}
	if len(t.Tags) > 0 {
		line += " [" + strings.Join(t.Tags, ",") + "]"
	}
	return line
}
